mapper.select:
select id, username, password, real_name as realName, phone, email, avatar_bucket as avatarBucket, avatar_object_key as avatarObjectKey, role, status, create_time as createTime, update_time as updateTime from user
username like concat('%',#{username},'%')
and real_name like concat('%',#{realName},'%')
and role = #{role,jdbcType=TINYINT}
and status = #{status,jdbcType=TINYINT}
order by id desc
